function response(body, contentType) {
  return new Response(body, { headers: { "content-type": contentType, "cache-control": "no-store" } });
}

function binaryResponse(base64, contentType) {
  const body = Uint8Array.from(atob(base64), (char) => char.charCodeAt(0));
  return new Response(body, { headers: { "content-type": contentType, "cache-control": "public, max-age=31536000, immutable" } });
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.pathname in assets) {
      return response(assets[url.pathname], url.pathname.endsWith(".css") ? "text/css; charset=utf-8" : "text/javascript; charset=utf-8");
    }
    if (url.pathname === "/pixel-agents" || url.pathname === "/pixel-agents/") {
      return response(pixelAgents, "text/html; charset=utf-8");
    }
    if (url.pathname === "/data/calendar-events.json" || url.pathname === "/back-office-javi-dashboard/data/calendar-events.json") {
      return response(calendarEvents, "application/json; charset=utf-8");
    }
    if (url.pathname === "/nono-avatar.jpg" || url.pathname === "/back-office-javi-dashboard/nono-avatar.jpg") {
      return binaryResponse(nonoAvatar, "image/jpeg");
    }
    return response(html, "text/html; charset=utf-8");
  }
};
